// Builds apps-script/Code.gs from the shared game core so there's one file to paste.
// Usage: node tools/build.js
const fs = require('fs');
const path = require('path');
const root = path.join(__dirname, '..');
const strip = (s) => s.replace(/\nif \(typeof module[^\n]*\n?/g, '\n');
const out = [
  '/**',
  ' * Favor Christmas Party — Mystery Kris Kringle Google Apps Script backend.',
  ' * Generated by tools/build.js — paste this whole file into Extensions → Apps Script.',
  ' * Then run setup() once, and Deploy → New deployment → Web app (Execute as: Me, Access: Anyone).',
  ' */',
  '',
  strip(fs.readFileSync(path.join(root, 'js/trivia-seed.js'), 'utf8')),
  strip(fs.readFileSync(path.join(root, 'js/animals.js'), 'utf8')),
  strip(fs.readFileSync(path.join(root, 'js/core.js'), 'utf8')),
  fs.readFileSync(path.join(root, 'apps-script/adapter.js'), 'utf8'),
].join('\n');
fs.writeFileSync(path.join(root, 'apps-script/Code.gs'), out);
console.log('Wrote apps-script/Code.gs (' + out.length + ' chars)');
